// ============================================================
// WF2 - Node Code: validasi input update.
// Field wajib: no_resi, nama_admin, status, lokasi.
// Tidak boleh kosong / hanya spasi. Status harus salah satu enum.
// Jika invalid => set flag valid=false + pesan error (respond 400 nanti).
// ============================================================

const ENUM_STATUS = [
  "Manifest",
  "On Process",
  "Transit",
  "Out for Delivery",
  "Delivered",
  "Failed/Return"
];

// Ambil body request dari webhook.
const body = ($json.body) ? $json.body : $json;

function bersih(v) {
  return (v === undefined || v === null) ? "" : String(v).trim();
}

const no_resi = bersih(body.no_resi).toUpperCase();
const nama_admin = bersih(body.nama_admin);
const status = bersih(body.status);
const lokasi = bersih(body.lokasi);

// Kumpulkan error validasi.
const errors = [];
if (!no_resi) errors.push("no_resi wajib diisi");
if (!nama_admin) errors.push("nama_admin wajib diisi");
if (!status) errors.push("status wajib diisi");
if (!lokasi) errors.push("lokasi wajib diisi");
if (status && !ENUM_STATUS.includes(status)) {
  errors.push("status tidak valid. Pilihan: " + ENUM_STATUS.join(", "));
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: errors.join("; ")
    }
  }];
}

// Valid: teruskan data bersih.
return [{
  json: {
    valid: true,
    no_resi: no_resi,
    nama_admin: nama_admin,
    status: status,
    lokasi: lokasi
  }
}];

// ============================================================
// WF2 - Node Code: proses update baris atau append baris baru.
// - Lookup baris sheet berdasarkan No_Resi.
// - Jika ada: parse riwayat (try/catch; jika korup mulai array baru namun
//   simpan raw lama sebagai catatan di elemen pertama), APPEND entri baru,
//   siapkan payload UPDATE by row_number.
// - Jika belum ada: siapkan payload APPEND baris baru dengan 1 entri.
// Output menandai mode: "update" atau "append" untuk routing node berikut.
// ============================================================

// Data hasil validasi (item pertama dari node Validasi).
const val = $items('Code Validasi Input')[0].json;
const no_resi = val.no_resi;
const nama_admin = val.nama_admin;
const status = val.status;
const lokasi = val.lokasi;

// Waktu sekarang dalam ISO 8601 dengan offset +07:00 (Asia/Jakarta).
function nowJakartaISO() {
  const now = new Date();
  // Konversi ke waktu Jakarta (UTC+7) lalu format manual dengan offset tetap.
  const jakartaMs = now.getTime() + (7 * 60 * 60 * 1000);
  const d = new Date(jakartaMs);
  const pad = (n) => String(n).padStart(2, '0');
  const yyyy = d.getUTCFullYear();
  const MM = pad(d.getUTCMonth() + 1);
  const dd = pad(d.getUTCDate());
  const hh = pad(d.getUTCHours());
  const mm = pad(d.getUTCMinutes());
  const ss = pad(d.getUTCSeconds());
  return `${yyyy}-${MM}-${dd}T${hh}:${mm}:${ss}+07:00`;
}

const waktu = nowJakartaISO();

// Entri riwayat baru sesuai kontrak.
const entriBaru = {
  waktu: waktu,
  status: status,
  lokasi: lokasi,
  admin: nama_admin
};

// Rows sheet dari node Baca Sheet.
const rows = $items('Baca Sheet Untuk Update').map(i => i.json);

// Cari baris yang cocok (No_Resi uppercase).
let baris = null;
for (const row of rows) {
  const key = String(row.No_Resi || '').trim().toUpperCase();
  if (key === no_resi) { baris = row; break; }
}

if (baris) {
  // ---- MODE UPDATE ----
  // Parse riwayat lama dengan aman.
  let riwayat = [];
  const raw = baris.Riwayat_Posisi_JSON;
  if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
    try {
      const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
      if (Array.isArray(parsed)) {
        riwayat = parsed;
      } else {
        throw new Error('bukan array');
      }
    } catch (e) {
      // JSON korup: mulai array baru, simpan raw lama sebagai catatan.
      riwayat = [{
        waktu: waktu,
        status: 'CATATAN_SISTEM',
        lokasi: 'Data riwayat lama korup, disimpan sebagai raw',
        admin: 'SISTEM',
        raw_lama: String(raw)
      }];
    }
  }

  // Append entri baru di akhir.
  riwayat.push(entriBaru);

  // row_number diperlukan Google Sheets untuk update by row.
  const rowNumber = baris.row_number;

  return [{
    json: {
      mode: 'update',
      row_number: rowNumber,
      No_Resi: baris.No_Resi,
      Pengirim: baris.Pengirim || '',
      Penerima: baris.Penerima || '',
      Status_Terakhir: status,
      Riwayat_Posisi_JSON: JSON.stringify(riwayat),
      Timestamp_Update: waktu,
      total_riwayat: riwayat.length
    }
  }];
} else {
  // ---- MODE APPEND (resi belum ada) ----
  const riwayat = [entriBaru];
  return [{
    json: {
      mode: 'append',
      No_Resi: no_resi,
      Pengirim: '',
      Penerima: '',
      Status_Terakhir: status,
      Riwayat_Posisi_JSON: JSON.stringify(riwayat),
      Timestamp_Update: waktu,
      total_riwayat: riwayat.length
    }
  }];
}
